import{_ as t,o as a,c as r,a6 as o}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"Runtime Behavioral Contracts","description":"","frontmatter":{},"headers":[],"relativePath":"runtime/index.md","filePath":"runtime/index.md","lastUpdated":1771970963000}'),i={name:"runtime/index.md"};function n(d,e,s,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /runtime.md for this page in Markdown format</div><h1 id="runtime-behavioral-contracts" tabindex="-1">Runtime Behavioral Contracts <a class="header-anchor" href="#runtime-behavioral-contracts" aria-label="Permalink to “Runtime Behavioral Contracts”">​</a></h1><blockquote><p><strong>Authority</strong>: Navigation (non-normative) <strong>Purpose</strong>: Index and layer boundary for runtime behavioral contracts.</p></blockquote><p>The <code>runtime/</code> layer defines externally observable behavioral contracts for <code>@sideband/runtime</code> — the session lifecycle, message routing, and RPC correlation semantics that peer and application layers depend on.</p><p>These contracts sit above wire encoding. Wire-level rules remain in <a href="./../protocols/"><code>docs/protocols/</code></a>. Runtime docs may reference protocol docs; they MUST NOT restate or redefine wire-level invariants.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to “Documents”">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Scope</th><th>Authority</th></tr></thead><tbody><tr><td><a href="./session">session.md</a></td><td>Session states, negotiators, retry, termination</td><td>Primary</td></tr><tr><td><a href="./router">router.md</a></td><td>Handler registration, dispatch ordering, error propagation</td><td>Primary</td></tr></tbody></table><h2 id="key-invariants" tabindex="-1">Key Invariants <a class="header-anchor" href="#key-invariants" aria-label="Permalink to “Key Invariants”">​</a></h2><ul><li>A <code>Peer</code> owns zero or more <code>Session</code> instances; at most one may be <code>Active</code> per peer in v1.</li><li>Session retry is opt-in and per-session; it uses exponential backoff.</li><li><code>Router</code> dispatch is deterministic: exact match before prefix, registration order within each bucket.</li><li><code>cid</code> (correlation ID) is set by the request and echoed unchanged by the response; the runtime matches on <code>cid</code>, never on <code>frameId</code>.</li></ul><h2 id="adrs" tabindex="-1">ADRs <a class="header-anchor" href="#adrs" aria-label="Permalink to “ADRs”">​</a></h2><ul><li><a href="./../adr/009-runtime-peer-lifecycle">ADR-009</a> — Session lifecycle design and negotiator interface</li><li><a href="./../adr/010-rpc-correlation-cid">ADR-010</a> — RPC correlation via <code>cid</code></li><li><a href="./../adr/011-runtime-message-routing">ADR-011</a> — Message routing and dispatch rules</li></ul>',11)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
